def compute(vars):
    prior_year_profit = vars["v1"]
    latest_year_profit = vars["v2"]
    if prior_year_profit == 0:
        return None
    change_ratio = (latest_year_profit - prior_year_profit) / prior_year_profit
    projected_profit = latest_year_profit * (1 + change_ratio)
    return {
        "value": projected_profit,
        "trace": {
            "prior_year_profit": prior_year_profit,
            "latest_year_profit": latest_year_profit,
            "change_ratio": change_ratio,
            "projected_profit": projected_profit,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": None
            }
        }
    }
